import{_ as a,a as r,b as i}from"./chunks/CORVON743V1_PortsConnection.DtH5Xu3f.js";import{_ as n,C as s,o as l,c as d,j as e,a as c,E as h,al as p}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"CORVON 743v1","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/corvon_743v1.md","filePath":"en/flight_controller/corvon_743v1.md"}'),u={name:"en/flight_controller/corvon_743v1.md"};function g(m,t,f,b,C,v){const o=s("Badge");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"corvon-743v1",tabindex:"-1"},[c("CORVON 743v1 "),e("a",{class:"header-anchor",href:"#corvon-743v1","aria-label":'Permalink to "CORVON 743v1"'},"​")],-1)),h(o,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=p('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the manufacturer for hardware support or compliance issues.</p></div><p>The <em>CORVON 743v1</em> is a flight controller designed by Feikong Technology Co., Ltd under the CORVON brand. It features a powerful STM32H743 processor, dual high-performance IMUs (BMI088/BMI270), and an extensive array of interfaces.</p><p>With its highly integrated 36x36mm footprint and 9g weight, and specialized interfaces like a direct plug-and-play DJI O3 Air Unit connector, this flight controller is optimized for space-constrained FPV builds and agile multirotors that require top-tier processing power and sensor redundancy.</p><p>The board uses <a href="./../flight_controller/autopilot_pixhawk_standard">Pixhawk Autopilot Standard Connections</a>.</p><p><img src="'+a+'" width="400px" title="CORVON 743v1 Top Baseboard"> <img src="'+r+'" width="400px" title="CORVON 743v1 Bottom Interfaces"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>MCU:</strong> STM32H743VIT6 MCU (32 Bit Arm® Cortex®-M7, 480MHz, 2MB Flash, 1MB RAM)</li><li><strong>IMU:</strong> Bosch BMI088, BMI270 (Dual IMU redundancy)</li><li><strong>Barometer:</strong> DPS310</li><li><strong>Magnetometer:</strong> IST8310</li><li><strong>OSD:</strong> Onboard AT7456E</li><li><strong>Interfaces:</strong><ul><li>7x UARTs</li><li>1x CAN (UAVCAN)</li><li>1x I2C</li><li>Dedicated RC Input (UART6)</li><li>10x PWM outputs (DShot &amp; Bi-Directional DShot supported)</li><li>Dedicated DJI O3 Air Unit connector</li></ul></li><li><strong>Power:</strong><ul><li>9V 3A BEC</li><li>5V 3A BEC</li><li>ADC for battery voltage (up to 6S) and current monitoring</li></ul></li></ul><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p>Order from <a href="https://corvon.tech" target="_blank" rel="noreferrer">CORVON</a>.</p><h2 id="physical-mechanical" tabindex="-1">Physical / Mechanical <a class="header-anchor" href="#physical-mechanical" aria-label="Permalink to &quot;Physical / Mechanical&quot;">​</a></h2><ul><li><strong>Mounting:</strong> 30.5 x 30.5mm, Φ4mm</li><li><strong>Dimensions:</strong> 36 x 36 x 8 mm</li><li><strong>Weight:</strong> 9g</li></ul><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li><strong>FMU Processor:</strong> STM32H743 <ul><li>32 Bit Arm® Cortex®-M7, 480MHz</li><li>2MB Flash, 1MB RAM</li></ul></li><li><strong>On-board Sensors:</strong><ul><li>Accel/Gyro: Bosch BMI088, BMI270</li><li>Barometer: DPS310</li><li>Compass: IST8310</li></ul></li></ul><h3 id="power-configuration" tabindex="-1">Power Configuration <a class="header-anchor" href="#power-configuration" aria-label="Permalink to &quot;Power Configuration&quot;">​</a></h3><p>The board has an internal voltage sensor and connections on the ESC connector for an external current sensor.</p><ul><li>The voltage sensor handles up to 6S LiPo batteries.</li><li>Two onboard BECs provide robust peripheral power (9V 3A and 5V 3A).</li></ul><h2 id="connectors-pinouts" tabindex="-1">Connectors &amp; Pinouts <a class="header-anchor" href="#connectors-pinouts" aria-label="Permalink to &quot;Connectors &amp; Pinouts&quot;">​</a></h2><p>The following image shows the port connection details, including RC, UARTs, CAN, I2C, SWD Debug, and VTX connections.</p><img src="'+i+'" width="800px" title="CORVON 743v1 Ports"><h3 id="standard-serial-port-mapping" tabindex="-1">Standard Serial Port Mapping <a class="header-anchor" href="#standard-serial-port-mapping" aria-label="Permalink to &quot;Standard Serial Port Mapping&quot;">​</a></h3><table tabindex="0"><thead><tr><th>UART</th><th>PX4 Target Config</th><th>Default Usage</th></tr></thead><tbody><tr><td>USART1</td><td>TELEM1</td><td>MAVLink</td></tr><tr><td>UART4</td><td>TELEM2</td><td>MAVLink</td></tr><tr><td>USART2</td><td>GPS1</td><td>GPS</td></tr><tr><td>USART3</td><td>TELEM3</td><td></td></tr><tr><td>UART8</td><td>URT6</td><td></td></tr><tr><td>USART6</td><td>RC</td><td>RC Input</td></tr><tr><td>UART7</td><td>TELEM4</td><td>ESC Telemetry</td></tr></tbody></table><h3 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h3><p>The board features a <strong>4-pin SWD Debug</strong> interface located on the right side of the board. This includes <code>SWCLK</code>, <code>SWDIO</code>, <code>3V3</code>, and <code>GND</code> for full hardware debugging. While a dedicated UART isn&#39;t strictly reserved for the NSH console by default, the full-speed USB connection provides MAVLink Console access out of the box.</p><h3 id="rc-input" tabindex="-1">RC Input <a class="header-anchor" href="#rc-input" aria-label="Permalink to &quot;RC Input&quot;">​</a></h3><p>RC Input is mapped to <strong>UART6</strong> via the explicit <code>SBUS/CRSF</code> connector block.</p><ul><li>It fully supports PX4&#39;s standard <code>RC_INPUT</code> module protocols.</li><li>The connector exposes both <code>RX6</code> and <code>TX6</code>, which makes it fully capable of bidirectional receiver protocols such as TBS Crossfire (CRSF), ELRS, and FPort, as well as traditional single-wire standards like SBUS (which operates inverted on RX6).</li></ul><h2 id="building-loading-firmware" tabindex="-1">Building/Loading Firmware <a class="header-anchor" href="#building-loading-firmware" aria-label="Permalink to &quot;Building/Loading Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware (from PX4 v1.18). It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_743v1_default</span></span></code></pre></div><p>Initial firmware flashing can be done over USB via QGroundControl. The bootloader status aligns with standard generic PX4 LED indications (Red = Bootloader/Error, Blue = Active/Activity, Green = Powered).</p>',33))])}const _=n(u,[["render",g]]);export{S as __pageData,_ as default};
